use vstd::prelude::*;

verus! {
    // Specification for the interleave function
    fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
        requires
            // All three input vectors must have the same length
            s1.len() == s2.len() && s2.len() == s3.len() &&
            // The length of the vectors must be non-negative
            s1.len() <= (i32::MAX as usize) / 3,
        ensures
            // The resulting vector must have length exactly 3 times the input length
            res.len() == 3 * s1.len() &&
            // The elements of the result must be interleaved correctly
            forall|i: nat| (i < s1.len() as nat) ==> 
                res[3 * i as usize] == s1[i as usize] &&
                res[3 * i as usize + 1] == s2[i as usize] &&
                res[3 * i as usize + 2] == s3[i as usize]
    {
        let mut res: Vec<i32> = Vec::with_capacity(3 * s1.len());
        let len = s1.len();
        
        let mut idx: usize = 0;
        while idx < len
            invariant
                idx <= len,
                res.len() == 3 * idx,
                res.len() <= 3 * len,
            decreases len - idx,
        {
            res.push(s1[idx]);
            res.push(s2[idx]);
            res.push(s3[idx]);
            idx = idx + 1;
        }
        
        res
    }
}

